AW = {"H": 1.0, "O": 16, "S": 32, "Pb": 207, "Na": 23, "Cl": 35.5, "Cu": 63.5, "Fe": 56, "Ag": 108}


def _parse(s):
    st, i = [Counter()], 0
    while i < len(s):
        if s[i] in "([":
            st.append(Counter()); i += 1
        elif s[i] in ")]":
            m = re.match(r"\d*", s[i + 1:]); k = int(m.group() or 1); i += 1 + len(m.group())
            top = st.pop()
            for e, c in top.items():
                st[-1][e] += k * c
        else:
            m = re.match(r"([A-Z][a-z]?)(\d*)", s[i:])
            st[-1][m.group(1)] += int(m.group(2) or 1); i += len(m.group())
    return st[0]


def Mr(f):
    return sum(AW[e] * c for e, c in _parse(f).items())


def balanced(lhs, rhs):
    """[(係数, 化学式, 電荷)]。電子は ('', -1)。原子の数と電荷の両方を確かめる"""
    def tot(side):
        t, q = Counter(), 0
        for k, f, z in side:
            for e, c in _parse(f).items():
                t[e] += k * c
            q += k * z
        return +t, q
    assert tot(lhs) == tot(rhs), (lhs, rhs)


def verify():
    items = CH[4]["items"]
    lv = [it["lv"] for it in items]
    assert lv == sorted(lv) and lv.count("A") == 4 and 4 <= lv.count("B") <= 5 and lv.count("C") == 2
    for it in items:
        for k in ("tag", "q", "a", "s"):
            assert it[k].strip(), k
        for k in ("q", "a", "s"):
            assert it[k].count("$") % 2 == 0 and "$$" not in it[k], it[k][:30]
        assert "<b>ポイント</b>" in it["s"]
    assert CH[4]["goal"].count("$") % 2 == 0

    def sig(x, n=2):
        return round(x, n - 1 - int(floor(log10(abs(x)))))

    def eq(x, v, n=2):
        assert abs(sig(x, n) - v) <= 1e-9 * abs(v), (x, sig(x, n), v)

    # A1 酸化数：既知の原子の酸化数の和＋（求める原子の数）×x＝電荷
    def ox(known, cnt, charge=0):
        return (charge - known) / cnt
    assert ox(2 * 1 + 4 * -2, 1) == 6 and ox(1 + 4 * -2, 1) == 7 and ox(2 * 1 + 7 * -2, 2) == 6
    assert ox(4 * 1, 1, +1) == -3 and ox(2 * 1, 2) == -1 and ox(1, 1) == -1
    # A2 反応式
    balanced([(1, "SO2", 0), (2, "H2S", 0)], [(3, "S", 0), (2, "H2O", 0)])
    balanced([(1, "H2O2", 0), (2, "KI", 0), (1, "H2SO4", 0)], [(1, "I2", 0), (1, "K2SO4", 0), (2, "H2O", 0)])
    balanced([(2, "KMnO4", 0), (5, "H2O2", 0), (3, "H2SO4", 0)],
             [(2, "MnSO4", 0), (1, "K2SO4", 0), (5, "O2", 0), (8, "H2O", 0)])
    balanced([(1, "Cl2", 0), (2, "KBr", 0)], [(2, "KCl", 0), (1, "Br2", 0)])
    # A3, A4
    balanced([(1, "Cu", 0), (2, "Ag", 1)], [(1, "Cu", 2), (2, "Ag", 0)])
    balanced([(1, "Zn", 0)], [(1, "Zn", 2), (2, "", -1)]); balanced([(1, "Cu", 2), (2, "", -1)], [(1, "Cu", 0)])
    # B1 過マンガン酸カリウム滴定
    balanced([(1, "MnO4", -1), (8, "H", 1), (5, "", -1)], [(1, "Mn", 2), (4, "H2O", 0)])
    balanced([(1, "(COOH)2", 0)], [(2, "CO2", 0), (2, "H", 1), (2, "", -1)])
    balanced([(2, "MnO4", -1), (5, "(COOH)2", 0), (6, "H", 1)], [(2, "Mn", 2), (10, "CO2", 0), (8, "H2O", 0)])
    balanced([(1, "H2O2", 0)], [(1, "O2", 0), (2, "H", 1), (2, "", -1)])
    c = 0.0500 * 10.0 * 2 / 5 / 8.00; eq(c, 2.50e-2, 3)
    nh2o2 = c * 16.0e-3 * 5 / 2; eq(nh2o2, 1.00e-3, 3); eq(nh2o2 / 0.0100 * 10, 1.00, 3)
    assert Mr("H2O2") == 34; eq(1.00 * 34 / 1000 * 100, 3.4)
    # B2 ヨウ素滴定
    balanced([(1, "ClO", -1), (2, "I", -1), (2, "H", 1)], [(1, "Cl", -1), (1, "I2", 0), (1, "H2O", 0)])
    balanced([(1, "I2", 0), (2, "S2O3", -2)], [(2, "I", -1), (1, "S4O6", -2)])
    ni2 = 0.100 * 12.0e-3 / 2; eq(ni2, 6.00e-4, 3); eq(ni2 / 0.0100 * 10, 0.600, 3)
    assert Mr("NaClO") == 74.5; eq(0.600 * 74.5 / 1100 * 100, 4.1)
    # B3 鉛蓄電池
    balanced([(1, "Pb", 0), (1, "SO4", -2)], [(1, "PbSO4", 0), (2, "", -1)])
    balanced([(1, "PbO2", 0), (4, "H", 1), (1, "SO4", -2), (2, "", -1)], [(1, "PbSO4", 0), (2, "H2O", 0)])
    balanced([(1, "Pb", 0), (1, "PbO2", 0), (2, "H2SO4", 0)], [(2, "PbSO4", 0), (2, "H2O", 0)])
    ne = 0.200; eq(ne * 9.65e4 / 2.00, 9.65e3, 3)
    eq(ne / 2 * (Mr("PbSO4") - Mr("Pb")), 9.60, 3); eq(ne / 2 * (Mr("PbSO4") - Mr("PbO2")), 6.40, 3)
    h2so4 = 300 - ne * Mr("H2SO4"); sol = 1000 - ne * Mr("H2SO4") + ne * Mr("H2O")
    assert abs(sol - 984.0) < 1e-9; eq(h2so4 / sol * 100, 28.5, 3)
    # B4 硫酸銅の電気分解
    ne = 0.500 * (32 * 60 + 10) / 9.65e4; eq(ne, 1.00e-2, 3)
    eq(ne / 2 * 63.5, 0.318, 3); eq(ne / 4 * 22.4e3, 56.0, 3)
    balanced([(2, "H2O", 0)], [(1, "O2", 0), (4, "H", 1), (4, "", -1)])
    assert round(-log10(ne / 0.200), 1) == 1.3 and abs((2 - (1 - 0.30)) - 1.3) < 1e-9
    # B5 直列
    ne = 2.16 / 108; eq(ne * 9.65e4 / 1.00, 1.93e3, 3); eq(ne / 4 * 22.4e3, 112, 3); eq(ne / 2 * 22.4e3, 224, 3)
    balanced([(2, "Cl", -1)], [(1, "Cl2", 0), (2, "", -1)])
    balanced([(2, "H2O", 0), (2, "", -1)], [(1, "H2", 0), (2, "OH", -1)])
    # C1 燃料電池
    nh2 = 11.2 / 22.4; q = 2 * nh2 * 9.65e4; eq(q, 9.65e4, 3)
    e = q * 0.80 / 1000; eq(e, 77); assert round(e / (nh2 * 286) * 100) == 54
    balanced([(1, "O2", 0), (4, "H", 1), (4, "", -1)], [(2, "H2O", 0)])
    # C2 電解精錬
    ne = 5.00 * 1930 / 9.65e4; eq(ne, 0.100, 3); eq(ne / 2 * 63.5, 3.18, 3)
    y = (63.5 * ne / 2 - (3.268 - 0.108)) / (63.5 - 56); x = ne / 2 - y
    eq(y, 2.00e-3, 3); eq(ne / 2 - x, 2.00e-3, 3)
